mapper.select:
/* 관리자 품종 목록 (사용 안 함 포함) */ SELECT FROM VRTY
AND PET_SE_CD = #{petSeCd}
ORDER BY PET_SE_CD , SORT_SEQ , VRTY_SN

/* 관리자 품종 단건 (사용 안 함 포함) */
SELECT 
  FROM VRTY
 WHERE VRTY_SN = #{vrtySn}

/* 같은 구분에 공백을 지운 이름이 같은 품종 수 */
SELECT COUNT(*)
  FROM VRTY
 WHERE PET_SE_CD = #{petSeCd}
   AND REPLACE(VRTY_NM, ' ', '') = #{nameKey}

   AND VRTY_SN <> #{excludeVrtySn}

/* 구분의 가장 큰 정렬 순서 */
SELECT COALESCE(MAX(SORT_SEQ), 0)
  FROM VRTY
 WHERE PET_SE_CD = #{petSeCd}

mapper.insert:
/* 품종 등록 */
INSERT INTO VRTY
     ( VRTY_CD
     , PET_SE_CD
     , VRTY_NM
     , SORT_SEQ
     , USE_YN
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID
     )
VALUES
     ( #{vrtyCd}
     , #{petSeCd}
     , #{vrtyNm}
     , #{sortSeq}
     , #{useYn}
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId}
     )

mapper.update:
/* 품종 수정 (보낸 칸만) */
UPDATE VRTY

    VRTY_NM = #{vrtyNm},
    SORT_SEQ = #{sortSeq},
    USE_YN = #{useYn},
    MDFCN_DT = NOW(),
    MDFR_ID = #{mdfrId}

 WHERE VRTY_SN = #{vrtySn}
